<script setup>
import {computed,ref,watch} from 'vue';
import {useAgencyStore} from '../../store/agency.js';
import api from '../../services/api.js';
const props=defineProps({agencyId:[Number,String],http:Object});
const agency=useAgencyStore();
const id=computed(()=>Number(props.agencyId||agency.currentAgency?.id));
const client=computed(()=>props.http||api);
const form=ref(null),subjects=ref(''),grades=ref(''),loading=ref(false),saving=ref(false),error=ref(''),notice=ref('');let generation=0;
async function load(){const current=++generation;form.value=null;saving.value=false;error.value='';notice.value='';if(!id.value)return;loading.value=true;try{const {data}=await client.value.get('/tutoring-workspace/profile',{params:{agencyId:id.value}});if(current!==generation)return;form.value=data.profile;subjects.value=form.value.subjectAreas.join(', ');grades.value=form.value.gradeLevels.join(', ');}catch(e){if(current===generation)error.value=e.response?.data?.error?.message||'Your tutoring profile could not be loaded.';}finally{if(current===generation)loading.value=false;}}
async function save(){const current=generation;saving.value=true;error.value='';notice.value='';try{const {data}=await client.value.put('/tutoring-workspace/profile',{agencyId:id.value,subjectAreas:subjects.value.split(',').map(s=>s.trim()).filter(Boolean),gradeLevels:grades.value.split(',').map(s=>s.trim()).filter(Boolean),bio:form.value.bio,acceptingNewStudents:form.value.acceptingNewStudents});if(current!==generation)return;form.value=data.profile;notice.value='Tutoring profile saved for this agency.';}catch(e){if(current===generation)error.value=e.response?.data?.error?.message||'Your changes could not be saved. Your entries are still here.';}finally{if(current===generation)saving.value=false;}}
const money=value=>value==null?'Not assigned':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(value/100)+' / hour';
watch(id,load,{immediate:true});
</script>
<template><main class="tutor-profile"><h1>Tutoring profile</h1><p>Subjects, grades and your public introduction help families find the right tutor. Your agency manages service approvals, customer prices and pay.</p><p v-if="loading" role="status">Loading your profile…</p><p v-if="error" role="alert">{{error}} <button @click="load" :disabled="loading||saving">Try again</button></p><p v-if="notice" role="status">{{notice}}</p><form v-if="form" @submit.prevent="save"><label>Subjects, separated by commas<input v-model="subjects" required maxlength="1500" placeholder="Math, Reading"/></label><label>Grades, separated by commas<input v-model="grades" required maxlength="200" placeholder="3, 5"/></label><label>Public introduction<textarea v-model="form.bio" maxlength="4000" rows="5"/></label><label class="check"><input type="checkbox" v-model="form.acceptingNewStudents"/>Accepting new students</label><section><h2>Assigned customer pricing</h2><p>Learning level: {{form.learningLevel||'Not assigned'}}</p><p>Virtual: {{money(form.hourlyRates?.virtual)}}</p><p>In person: {{money(form.hourlyRates?.['in-person'])}}</p><p>These are family prices. View your own compensation in My Account → Compensation.</p></section><button type="submit" :disabled="saving||loading">{{saving?'Saving…':'Save tutoring profile'}}</button></form><p v-if="!loading&&!error&&!id">Choose your authorized agency to continue.</p></main></template>
<style scoped>.tutor-profile{max-width:760px;margin:0 auto;padding:24px;color:var(--text-primary,#203b5b)}h1{font-size:26px}h2{font-size:18px}p{line-height:1.6}label{display:grid;gap:7px;margin:18px 0}input,textarea,button{font:inherit;padding:11px;border:1px solid #b5c6d8;border-radius:8px;max-width:100%;box-sizing:border-box}button{cursor:pointer;min-height:44px}.check{display:flex;align-items:center}section{padding:14px;background:#f1f6fb;border-radius:10px}[role=alert]{color:#a52d37}:focus-visible{outline:3px solid #4e86c9;outline-offset:2px}</style>
